   "id": "central-bank-money",
   "title": "Central Bank Money",
   "short": "",
   "parent": "money",
   "order": 4.0,
   "summary": "Banknotes and the reserves banks hold at the central bank: the base layer of the modern money system.",
   "tcodes": [],
